using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Reflection;using System.Diagnostics;
namespace PZ3D {static class OwnedReviewRegressionTests {
 static int checks;static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 static void Put(string p,string s){Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,s);}
 static string Game(string root){foreach(string name in new[]{"ProjectZomboid64.exe","projectzomboid.jar","jre64/bin/java.exe","jre64/bin/server/jvm.dll","steam_api64.dll","ZNetJNI64.dll","Lighting64.dll"})Put(Path.Combine(root,name),"owned fixture");Put(Path.Combine(root,"ProjectZomboid64.json"),"{}");Put(Path.Combine(root,"game-version.txt"),"42.21.0");Put(Path.Combine(root,"version.txt"),"42.21.0");File.Copy(Path.Combine(Environment.GetEnvironmentVariable("OZL_REVIEW_PHASE"),"projectzomboid.jar"),Path.Combine(root,"projectzomboid.jar"),true);return root;}
 static string Mods(params string[] ids){return "mods\n{\n"+string.Join("",ids.Select(id=>" mod = "+id+",\n"))+"}\nmaps\n{\n}\n";}
 static void Mod(string user,string id,string requires=""){Put(Path.Combine(user,"mods",id,"42/mod.info"),"id="+id+"\n"+(requires==""?"":"require="+requires+"\n"));}
 static Engine Bound(string game,string user,string data,string id){var selected=new LaunchConfigurationProfiles(data,game,user).Resolve(id);var e=new Engine(selected.Context==null?selected.Snapshot.GamePath:selected.Context.Game,selected.Context==null?selected.Snapshot.UserPath:selected.Context.User,data,true,null,_=>new Process[0]);e.BindConfiguration(selected);return e;}
 static void Recovery(string root){string steam=Game(Path.Combine(root,"steam")),user=Path.Combine(root,"user"),data=Path.Combine(root,"data");var versions=new VersionLibrary(data,steam,user);var a=versions.Import(Game(Path.Combine(root,"A")),"A");var b=versions.Import(Game(Path.Combine(root,"B")),"B");foreach(string mode in new[]{"builtin","deleted","retargeted"}){versions.Select(a.Id);var profiles=new LaunchConfigurationProfiles(data,steam,user);var named=mode=="builtin"?null:profiles.Create(mode,a.Id,new string[0]);string id=named==null?"launcher":named.Id;profiles.Select(id);var owner=Bound(steam,user,data,id);if(mode=="builtin")File.Copy(Environment.GetEnvironmentVariable("OZL_OWNED_PROCESS_FIXTURE"),Path.Combine(owner.Game,"jre64/bin/java.exe"),true);LaunchProfiles.Stage(owner,new ProfileLaunchRequest{Kind="normal"});Process running=mode=="builtin"?Process.Start(LaunchProfiles.BuildStartInfo(owner)):null;if(running!=null)LaunchProfiles.RecordStartedProcess(owner,running);try{if(mode=="deleted")profiles.Delete(id);if(mode=="retargeted")profiles.SetVersion(id,b.Id);versions.Select(b.Id);profiles.Select("launcher");using(var fresh=new ModernController(steam,user,data,true)){var method=typeof(ModernController).GetMethod("RuntimeConfigurationController",BindingFlags.Instance|BindingFlags.NonPublic);var child=(ModernController)method.Invoke(fresh,null);Check(child!=null,"fresh root discovers imported A after "+mode);var engine=(Engine)typeof(ModernController).GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(child);Check(VersionLibrary.Same(engine.Game,a.GamePath)&&VersionLibrary.Same(engine.User,a.UserPath)&&engine.OwnedConfiguration.ProfileId==(named==null?null:id),"recovery keeps exact A game/user/profile after "+mode);if(running!=null){var json=new System.Web.Script.Serialization.JavaScriptSerializer();var record=json.Deserialize<ProfileSessionRecord>(File.ReadAllText(LaunchProfiles.Journal(engine)));Check(record.Pid==running.Id&&record.Birth==running.StartTime.ToUniversalTime().Ticks,"fresh root preserves actual A PID and birth evidence");var preview=json.Deserialize<Dictionary<string,object>>(json.Serialize(fresh.Execute("gameProcesses",new Dictionary<string,object>())));Check(json.Serialize(preview["clients"]).Contains("\"pid\":"+running.Id),"fresh root process preview targets running imported A");fresh.Execute("forceCloseGame",new Dictionary<string,object>{{"stamp",preview["stamp"]},{"confirmed",true}});Check(running.WaitForExit(5000),"fresh root confirmed close stops exact owned A fixture");}fresh.Execute("profileRecover",new Dictionary<string,object>());Check(!LaunchProfiles.Pending(owner)&&new LaunchConfigurationProfiles(data,steam,user).Selected().Context.Game==b.GamePath,"recover only A and retain B selection after "+mode);}}finally{if(running!=null){if(!running.HasExited){Put(Path.Combine(owner.Game,"native-stop"),"");running.WaitForExit(5000);}running.Dispose();}}}}
 static void SnapshotRecovery(string root){string game=Game(Path.Combine(root,"steam")),user=Path.Combine(root,"user"),data=Path.Combine(root,"data");var versions=new VersionLibrary(data,game,user);var a=versions.Import(Game(Path.Combine(root,"A")),"A");var b=versions.Import(Game(Path.Combine(root,"B")),"B");versions.Select(a.Id);var owner=Bound(game,user,data,"launcher");Put(Path.Combine(owner.User,"Saves/Sandbox/Source/mods.txt"),Mods());var service=new SaveEnvironments(owner);var preview=service.Preview("Sandbox/Source");var row=service.Create("Sandbox/Source",Path.Combine(root,"snapshot"),"Snapshot A",preview.stamp,CancellationToken.None,null,r=>SaveEnvironmentRuntime.Prepare(owner,r));var frozen=Bound(game,user,data,"snapshot:"+row.Id);LaunchProfiles.Stage(frozen,new ProfileLaunchRequest{Kind="normal"});versions.Select(b.Id);using(var fresh=new ModernController(game,user,data,true)){var child=(ModernController)typeof(ModernController).GetMethod("RuntimeConfigurationController",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(fresh,null);var engine=child==null?null:(Engine)typeof(ModernController).GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(child);Check(engine!=null&&engine.FrozenEnvironment!=null&&engine.FrozenEnvironment.Id==row.Id&&engine.User==a.UserPath,"fresh root discovers registered imported-A snapshot independently of selected B");fresh.Execute("profileRecover",new Dictionary<string,object>());Check(!LaunchProfiles.Pending(frozen),"registered snapshot journal recovers exact copied game/user pair");}}
 static void Named(string root){string game=Game(Path.Combine(root,"game")),user=Path.Combine(root,"user"),data=Path.Combine(root,"data");Mod(user,"LuaA","Dep");Mod(user,"Dep");Put(Path.Combine(user,"Saves/Sandbox/Source/mods.txt"),Mods("UnavailableOld"));byte[] original=File.ReadAllBytes(Path.Combine(user,"Saves/Sandbox/Source/mods.txt"));var profiles=new LaunchConfigurationProfiles(data,game,user);var named=profiles.Create("Named","steam",new[]{"LuaA"});var e=Bound(game,user,data,named.Id);var service=new SaveEnvironments(e);var preview=service.Preview("Sandbox/Source");Check(preview.ready,"named capture must exclude absent source-save ordinary mod: "+string.Join(";",preview.warnings));var row=service.Create("Sandbox/Source",Path.Combine(root,"snapshot"),"Named",preview.stamp,CancellationToken.None,null,r=>SaveEnvironmentRuntime.Prepare(e,r));Check(row.DefaultModIds.SequenceEqual(new[]{"LuaA"})&&row.ModRoots.SelectMany(r=>r.ModIds).OrderBy(x=>x).SequenceEqual(new[]{"Dep","LuaA"}),"named capture copies exactly selected ordinary dependency closure");Check(row.ModIds.SequenceEqual(new[]{"UnavailableOld"})&&row.SaveModsBytes.SequenceEqual(original)&&File.ReadAllBytes(Path.Combine(user,"Saves/Sandbox/Source/mods.txt")).SequenceEqual(original),"named original provenance remains exact and inactive");NamedDispatch(game,user,data,row,original);var builtin=new SaveEnvironments(Bound(game,user,data,"launcher")).Preview("Sandbox/Source");Check(!builtin.ready&&builtin.missing.Any(item=>item.modId=="UnavailableOld"),"builtin capture retains actual save ordinary requirements");var vanilla=Bound(game,user,data,"vanilla");var clean=new SaveEnvironments(vanilla);var cleanPreview=clean.Preview("Sandbox/Source");Check(cleanPreview.ready,"vanilla capture ignores source ordinary requirements");var empty=clean.Create("Sandbox/Source",Path.Combine(root,"vanilla"),"Vanilla",cleanPreview.stamp,CancellationToken.None,null,r=>SaveEnvironmentRuntime.Prepare(vanilla,r));Check(empty.ModRoots.Length==0&&empty.DefaultModIds.Length==0&&empty.SaveModsBytes.SequenceEqual(original),"vanilla snapshot is empty with exact provenance");}
 static void NamedDispatch(string game,string user,string data,SaveEnvironmentRecord row,byte[] original){
  var profiles=new LaunchConfigurationProfiles(data,game,user);var json=new System.Web.Script.Serialization.JavaScriptSerializer();string save=Path.Combine(user,"Saves/Sandbox/Source/mods.txt"),defaults=Path.Combine(user,"mods/default.txt");Put(defaults,Mods("OriginalDefault"));byte[] defaultBytes=File.ReadAllBytes(defaults);
  foreach(string id in new[]{"snapshot:"+row.Id,"launcher"}){
   profiles.Select(id);using(var controller=new ModernController(game,user,data,true)){
    var begin=json.Deserialize<Dictionary<string,object>>(json.Serialize(controller.Execute("startupBegin",new Dictionary<string,object>{{"targetKind","save"},{"targetId","Sandbox/Source"}})));
    var report=(LaunchPreflightReport)controller.Execute("launchPreflight",new Dictionary<string,object>{{"targetKind","save"},{"startupId",begin["startupId"]}});
    Check(report.canLaunch,id+" dispatcher preflight accepts effective named frozen list: "+json.Serialize(report));
    var child=(ModernController)typeof(ModernController).GetMethod("ConfigurationController",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(controller,null);var attempt=typeof(ModernController).GetField("startupAttempt",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(child);var resolved=(Engine)attempt.GetType().GetField("ResolvedEngine",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(attempt);
    Check(resolved.FrozenEnvironment!=null&&resolved.FrozenEnvironment.Id==row.Id,id+" resolves captured named snapshot");controller.Execute("startupCancel",new Dictionary<string,object>{{"startupId",begin["startupId"]}});
    LaunchProfiles.Stage(resolved,new ProfileLaunchRequest{Kind="save",Id="Sandbox/Source",Mode="Sandbox",Save="Source"});try{var info=LaunchProfiles.BuildStartInfo(resolved);var record=json.Deserialize<ProfileSessionRecord>(File.ReadAllText(LaunchProfiles.Journal(resolved)));Check(info.WorkingDirectory==row.GamePath&&VersionLibrary.Same(info.FileName,Path.Combine(row.GamePath,"jre64/bin/java.exe"))&&info.Arguments.Contains("-javaagent:")&&info.Arguments.Contains("OrangeEnvironment.jar")&&info.Arguments.Contains("-cachedir="+user)&&record.SnapshotId==row.Id&&record.SnapshotManifestHash==row.ManifestHash,id+" production staging pins copied runtime and revision");}finally{LaunchProfiles.Recover(resolved,true);}
    Check(File.ReadAllBytes(save).SequenceEqual(original)&&File.ReadAllBytes(defaults).SequenceEqual(defaultBytes),id+" stage and recovery preserve original save/default bytes");
   }
  }
  profiles.Select("launcher");using(var controller=new ModernController(game,user,data,true)){try{Put(save,Mods("ChangedSource"));var begin=json.Deserialize<Dictionary<string,object>>(json.Serialize(controller.Execute("startupBegin",new Dictionary<string,object>{{"targetKind","save"},{"targetId","Sandbox/Source"}})));bool refused=false;try{controller.Execute("launchPreflight",new Dictionary<string,object>{{"targetKind","save"},{"startupId",begin["startupId"]}});}catch(IOException){refused=true;}Check(refused,"automatic binding still rejects changed original provenance");}finally{File.WriteAllBytes(save,original);}}
 }
 static void Choices(string root){string game=Game(Path.Combine(root,"game")),user=Path.Combine(root,"user"),data=Path.Combine(root,"data");foreach(string id in new[]{"NewMod","OldComponent","NewComponent","SkipComponent","ZombieBuddy"})Mod(user,id);Mod(user,"OldComponent","UnavailableOldDependency");string java=Path.Combine(user,"mods/SkipJava/42/fixture.jar");Put(Path.Combine(user,"mods/SkipJava/42/mod.info"),"id=SkipJava\njavaJarFile=fixture.jar\njavaPkgName=fixture.skipped\n");using(var stream=File.Create(java))using(var jar=new System.IO.Compression.ZipArchive(stream,System.IO.Compression.ZipArchiveMode.Create))using(var writer=new StreamWriter(jar.CreateEntry("fixture/skipped/Marker.class").Open()))writer.Write("owned fixture");Mod(user,"SkipComponent","UnavailableSkippedDependency");string save=Path.Combine(user,"Saves/Sandbox/Source/mods.txt");Put(save,Mods("OldMod"));byte[] original=File.ReadAllBytes(save);var e=Bound(game,user,data,"launcher");foreach(string id in new[]{"OldComponent","SkipComponent","ZombieBuddy","SkipJava"})e.OwnedComponents().Select(Path.Combine(user,"mods",id),id,true,CancellationToken.None);byte[] selectionBefore=File.ReadAllBytes(Path.Combine(e.OwnedConfiguration.ComponentsDirectory,"selection.json"));var choices=new Dictionary<string,string>{{"OldMod","NewMod"},{"OldComponent","NewComponent"},{"SkipComponent",""},{"ZombieBuddy",""},{"SkipJava",""}};var service=new SaveEnvironments(e,choices);var preview=service.Preview("Sandbox/Source");Check(preview.ready,"explicit choices capture is ready: "+string.Join(";",preview.warnings));var row=service.Create("Sandbox/Source",Path.Combine(root,"snapshot"),"Choices",preview.stamp,CancellationToken.None,null,r=>SaveEnvironmentRuntime.Prepare(e,r));Check(row.DefaultModIds.SequenceEqual(SnapshotModChoices.Apply(row.DefaultModIds,choices))&&row.DefaultModIds.Contains("NewMod")&&!row.DefaultModIds.Contains("OldMod"),"frozen defaults persist effective replacement identities");Check(row.ActiveComponentIds.SequenceEqual(new[]{"NewComponent"})&&row.DefaultModIds.Contains("NewComponent")&&!row.DefaultModIds.Contains("SkipComponent"),"component skip/replacement cannot reappear from active policy");Check(row.ModRoots.SelectMany(r=>r.ModIds).OrderBy(x=>x).SequenceEqual(new[]{"NewComponent","NewMod"}),"copied roots match effective policy only");Check(row.PreloadModIds.Length==0&&!File.ReadAllText(Path.Combine(row.GamePath,"ProjectZomboid64.json")).Contains("ZombieBuddy.jar"),"skipped Buddy absent from preload and actual frozen launch arguments");var frozen=Bound(game,user,data,"snapshot:"+row.Id);SaveEnvironmentRuntime.PrepareTarget(frozen,"normal",null);for(int launch=0;launch<2;launch++){var start=new ProcessStartInfo("python","\""+Environment.GetEnvironmentVariable("OZL_REVIEW_PROBE")+"\" run \""+Environment.GetEnvironmentVariable("OZL_REVIEW_PHASE")+"\" \""+row.RootPath+"\" \""+user+"\" \""+string.Join(",",row.DefaultModIds)+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=Process.Start(start)){string output=process.StandardOutput.ReadToEnd(),error=process.StandardError.ReadToEnd();process.WaitForExit();Console.WriteLine(output);if(process.ExitCode!=0)Console.WriteLine(error);Check(process.ExitCode==0,"captured JVM persistence/relaunch "+launch);}SaveEnvironmentRuntime.ValidateOwnedRuntime(frozen);}SaveEnvironmentRuntime.PrepareTarget(frozen,"save","Sandbox/Source");Check(File.ReadAllBytes(save).SequenceEqual(original)&&row.SaveModsBytes.SequenceEqual(original),"effective persistence and relaunch validate without source writes");Check(selectionBefore.SequenceEqual(File.ReadAllBytes(Path.Combine(e.OwnedConfiguration.ComponentsDirectory,"selection.json")))&&File.ReadAllText(e.Config)=="{}","snapshot choices preserve original selected-component state and launch JSON");}
 static int Main(){string root=Path.Combine(Path.GetTempPath(),"o4-review-"+Guid.NewGuid().ToString("N").Substring(0,8));int failed=0;foreach(var test in new Dictionary<string,Action<string>>{{"recovery",Recovery},{"snapshotRecovery",SnapshotRecovery},{"named",Named},{"choices",Choices}})try{test.Value(Path.Combine(root,test.Key));Console.WriteLine("PASS "+test.Key);}catch(Exception error){failed++;Console.WriteLine("FAIL "+test.Key+" "+error);}Console.WriteLine("Review regression "+checks+" assertions, failures="+failed+"; fixtures "+root);return failed==0?0:1;}
}}
